# region: gather
def gather(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
            return out
    return out

# region: digest
def digest(xs, limit=9):
    return [v if v <= limit else limit for v in xs]

# region: shape
def shape(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: fold
def fold(summary, bar=2):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return fold(shape(digest(gather(raw))))

